declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
    DO_LOW : BOOL;
    AERATION_E_STOP_NC : BOOL;
END_VAR
VAR_OUTPUT
    BLOWER_RUN : BOOL := FALSE;
    AERATION_BLOWER_CYCLE_COUNT : UINT := 0;
END_VAR
VAR
    tonStartDelay : TON;
    xRunPrev : BOOL := FALSE;
END_VAR

implementation:
tonStartDelay(IN := DO_LOW AND AERATION_E_STOP_NC, PT := T#5S);

IF DO_LOW AND AERATION_E_STOP_NC THEN
    BLOWER_RUN := tonStartDelay.Q;
ELSE
    BLOWER_RUN := FALSE;
END_IF;

IF BLOWER_RUN AND NOT xRunPrev THEN
    AERATION_BLOWER_CYCLE_COUNT := AERATION_BLOWER_CYCLE_COUNT + UINT#1;
END_IF;

xRunPrev := BLOWER_RUN;
